def check_chars(s1, s2):
    lookup = set(s2)                      # fast O(1) lookups
    return {ch: ch in lookup for ch in s1}

s1 = "hello"
s2 = "world"

print(check_chars(s1, s2))
# {'h': False, 'e': False, 'l': True, 'o': True}

# Keep every character (including repeats) in order
print([(ch, ch in s2) for ch in s1])
# [('h', False), ('e', False), ('l', True), ('l', True), ('o', True)]

# Are ALL characters found?
print(all(ch in s2 for ch in s1))          # False

# Without the 'in' operator (if the interviewer asks)
def contains(text, target):
    for c in text:
        if c == target:
            return True
    return False

for ch in s1:
    print(ch, contains(s2, ch))

num_list = [1, 2, 3, [4, 5]]

def flatten(items):
    result = []
    for item in items:
        if isinstance(item, list):
            result.extend(flatten(item))   # go inside
        else:
            result.append(item)
    return result

print(flatten(num_list))              # [1, 2, 3, 4, 5]
print(flatten([1, [2, [3, [4]]]]))    # [1, 2, 3, 4]  any depth

# Generator version
def flatten_gen(items):
    for item in items:
        if isinstance(item, list):
            yield from flatten_gen(item)
        else:
            yield item

print(list(flatten_gen(num_list)))    # [1, 2, 3, 4, 5]

# One-level only, with a comprehension
print([x for item in num_list for x in (item if isinstance(item, list) else [item])])
